import { Group, PlaneGeometry, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, Fn, fract, sin, abs, sub, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'hub-collection-card-2';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  const cardW = 2.6;
  const cardH = 3.4;

  // Engineered gradient backdrop plane (the "card surface")
  const gradNode = Fn(() => {
    const v = uv().y;
    const c1 = vec3(0.043, 0.043, 0.063); // surface
    const c2 = vec3(0.086, 0.086, 0.114); // ink
    let col = mix(c1, c2, smoothstep(0.0, 1.0, v));
    // horizontal vignette
    const horiz = smoothstep(0.0, 0.55, abs(sub(uv().x, 0.5)));
    col = col.mul(add(horiz.mul(0.18), 0.82));
    // subtle grain
    const n = fract(sin(add(mul(uv().x, 91.345), mul(uv().y, 47.853))));
    col = add(col, mul(sub(n, 0.5), 0.025));
    return col;
  })();

  const backMat = new MeshBasicNodeMaterial();
  backMat.colorNode = gradNode;
  backMat.transparent = true;
  const backGeom = new THREE.PlaneGeometry(cardW, cardH);
  const backMesh = new THREE.Mesh(backGeom, backMat);
  backMesh.position.z = 0.0;
  group.add(backMesh);

  // Accent hairline frame (slightly larger plane behind)
  const frameMat = new MeshBasicNodeMaterial();
  frameMat.colorNode = vec3(1.0, 0.165, 0.22); // accent
  const frameGeom = new THREE.PlaneGeometry(cardW + 0.025, cardH + 0.025);
  const frameMesh = new THREE.Mesh(frameGeom, frameMat);
  frameMesh.position.z = -0.005;
  group.add(frameMesh);

  // Image plane (orb-decor.png)
  const imgMat = new MeshBasicNodeMaterial();
  imgMat.transparent = true;
  const imgW = cardW - 0.28;
  const imgH = cardH - 0.28;
  const imgGeom = new THREE.PlaneGeometry(imgW, imgH);
  const imgMesh = new THREE.Mesh(imgGeom, imgMat);
  imgMesh.position.z = 0.02;
  group.add(imgMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // Contact shadow plane below the card to ground it
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.transparent = true;
  shadowMat.opacityNode = smoothstep(0.5, 0.0, abs(sub(uv().x, 0.5))).mul(0.45);
  const shadowGeom = new THREE.PlaneGeometry(cardW * 1.4, 0.45);
  const shadowMesh = new THREE.Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -cardH * 0.5 - 0.05, -0.01);
  shadowMesh.rotation.x = -Math.PI / 2 * 0; // keep flat in plane
  group.add(shadowMesh);

  // Entrance: weighted-settle fade-up
  group.userData.handlers = {};
  group.position.y = 0; // adapter sets scene position; we animate relative
  const tl = gsap.timeline();
  group.scale.set(0.98, 0.98, 0.98);
  group.userData.__opacity = { v: 0 };
  gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out', delay: 0.1 });
  gsap.to(group.userData.__opacity, {
    v: 1, duration: 0.6, ease: 'power2.out', delay: 0.1,
    onUpdate: () => {
      backMat.opacity = group.userData.__opacity.v;
      frameMat.opacity = group.userData.__opacity.v;
      imgMat.opacity = group.userData.__opacity.v;
      shadowMat.opacity = group.userData.__opacity.v * 0.45;
    }
  });
  backMat.opacity = 0; frameMat.opacity = 0; imgMat.opacity = 0; shadowMat.opacity = 0;

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.userData.__opacity);
    backGeom.dispose(); backMat.dispose();
    frameGeom.dispose(); frameMat.dispose();
    imgGeom.dispose(); imgMat.dispose();
    shadowGeom.dispose(); shadowMat.dispose();
  };

  return group;
}
